private const val MOD = 1000000007

private var n = 0
private var m = 0
private val a = IntArray(N)
private val b = IntArray(N)
private val c = IntArray(N)
private val z = IntArray(N)
private val A = IntArray(N)
private val B = IntArray(N)
private var K: Long = 0

private fun inc(x: IntArray, idx: Int, y: Int) {
    var v = x[idx] + y
    if (v >= MOD) v -= MOD
    x[idx] = v
}

private fun dec(x: IntArray, idx: Int, y: Int) {
    var v = x[idx] - y
    if (v < 0) v += MOD
    x[idx] = v
}

private fun mult(u: IntArray, v: IntArray) {
    java.util.Arrays.fill(z, 0)
    for (i in 0..249) {
        for (j in 0..249) {
            z[i + j] = ((z[i + j] + 1L * u[i] * v[j]) % MOD).toInt()
        }
    }
    for (i in 498 downTo 250) {
        for (j in 1..m) {
            inc(z, i - b[j], z[i])
        }
    }
    for (i in 0..249) u[i] = z[i]
}

