        if ((n and 1L) != 0L) {
            // mult(A, cArr)
            // Need a copy of cArr because mult modifies first argument
            for (i in 0 until N) tmp[i] = cArr[i]
            mult(A, tmp)
        }
        n = n shr 1
        for (i in 0 until N) tmp[i] = cArr[i]
        mult(cArr, tmp)
    }
}

